mapper.select:
SELECT T1.INDENTIFY_MARK AS indentifyMark, T1.ORG_INDENTIFY_MARK AS orgIndentifyMark, T1.REGIST_BANK_CODE AS bankCode, T1.IS_BELONG_BANK AS isBelongBank, T1.THE_BANK_NAME AS theBankName, T1.THE_BANK_CODE AS theBankCode, T1.HOLDER_MARK AS holderMark, T1.HOLDER_REGION AS holderRegion, T1.HOLDER_TYPE AS holderType, T1.PERSONAL_IDENTIFY_TYPE AS personalIdentifyType, T1.INSTITUTION_IDENTIFY_TYPE AS institutionIdentifyType, T1.OTHER_IDENTIFY_NAME AS otherIdentifyName, T1.IDENTIFY_NUMBER AS identifyNumber, T1.SPV_CAP_ACC_BANK AS spvCapAccBank, T1.OTHER_CAP_ACC_BANK AS otherCapAccBank, T1.SPV_REGIST_CODE AS spvRegistCode, T1.HOLDER_DATE AS holderDate, T1.HOLDER_NAME AS holderName, T1.HOLDER_SEX AS holderSex, T1.HOLDER_RISK_PREFER AS holderRiskPrefer, T1.HOLDER_CELLPHONE AS holderCellphone, T1.HOLDER_TELEPHONE AS holderTelephone, T1.HOLDER_EMAIL AS holderEmail, T1.REMARK AS remark, T1.STATUS AS status, T1.DEPT_CODE AS deptCode, T1.UPDATE_USER AS updateUser, T1.UPDATE_TIME AS updateTime, T1.CREATE_USER AS createUser, T1.ORG_CODE AS orgCode from chb_equ_sub T1 inner join chb_equ_hold th on th.INDENTIFY_MARK=T1.INDENTIFY_MARK and ifnull(th.ORG_INDENTIFY_MARK,'0')=ifnull(T1.ORG_INDENTIFY_MARK,'0') /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
(T1.SUBMIT_FEEDBACK_STATUS = '03' or T1.ORG_INDENTIFY_MARK is not null) /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
t1.REGIST_BANK_CODE = #{item.REGIST_BANK_CODE,jdbcType=VARCHAR} and t1.IDENTIFY_NUMBER = #{item.IDENTIFY_NUMBER,jdbcType=VARCHAR} and t1.HOLDER_NAME = #{item.HOLDER_NAME,jdbcType=VARCHAR}
and t1.PERSONAL_IDENTIFY_TYPE = #{item.PERSONAL_IDENTIFY_TYPE,jdbcType=VARCHAR}
and t1.INSTITUTION_IDENTIFY_TYPE = #{item.INSTITUTION_IDENTIFY_TYPE,jdbcType=VARCHAR}
and t1.OTHER_IDENTIFY_NAME = #{item.OTHER_IDENTIFY_NAME,jdbcType=VARCHAR}

SELECT * FROM ( SELECT ifnull((SELECT T.INDENTIFY_MARK FROM CHB_EQU_SUB T WHERE T.ORG_INDENTIFY_MARK = T1.INDENTIFY_MARK AND STATUS !='03' AND ROWNUM = 1),T1.INDENTIFY_MARK ) AS indentifyMark, T1.ORG_INDENTIFY_MARK AS orgIndentifyMark, T1.REGIST_BANK_CODE AS bankCode, T1.IS_BELONG_BANK AS isBelongBank, T1.THE_BANK_NAME AS theBankName, T1.THE_BANK_CODE AS theBankCode, T1.HOLDER_MARK AS holderMark, T1.HOLDER_REGION AS holderRegion, T1.HOLDER_TYPE AS holderType, T1.PERSONAL_IDENTIFY_TYPE AS personalIdentifyType, T1.INSTITUTION_IDENTIFY_TYPE AS institutionIdentifyType, T1.OTHER_IDENTIFY_NAME AS otherIdentifyName, T1.IDENTIFY_NUMBER AS identifyNumber, T1.SPV_CAP_ACC_BANK AS spvCapAccBank, T1.OTHER_CAP_ACC_BANK AS otherCapAccBank, T1.SPV_REGIST_CODE AS spvRegistCode, T1.HOLDER_DATE AS holderDate, T1.HOLDER_NAME AS holderName, T1.HOLDER_SEX AS holderSex, T1.HOLDER_RISK_PREFER AS holderRiskPrefer, T1.HOLDER_CELLPHONE AS holderCellphone, T1.HOLDER_TELEPHONE AS holderTelephone, T1.HOLDER_EMAIL AS holderEmail, T1.REMARK AS remark, T1.STATUS AS status, T1.DEPT_CODE AS deptCode, T1.UPDATE_USER AS updateUser, T1.UPDATE_TIME AS updateTime, T1.CREATE_USER AS createUser, T1.ORG_CODE AS orgCode, row_number() OVER(partition by concat_ws('_',T1.REGIST_BANK_CODE,T1.IDENTIFY_NUMBER,IFNULL(T1.HOLDER_NAME,''),IFNULL(T1.PERSONAL_IDENTIFY_TYPE,''),IFNULL(T1.INSTITUTION_IDENTIFY_TYPE,''),IFNULL(T1.OTHER_IDENTIFY_NAME,'')) order by t1.update_time desc) rank from chb_view_equ_sub T1 /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
T1.SUBMIT_FEEDBACK_STATUS = '03' /***三期CHB_SUBMIT_STATUS去除改造 20220310**/ AND concat_ws('_',T1.REGIST_BANK_CODE,T1.IDENTIFY_NUMBER,IFNULL(T1.HOLDER_NAME,''),IFNULL(T1.PERSONAL_IDENTIFY_TYPE,''),IFNULL(T1.INSTITUTION_IDENTIFY_TYPE,''),IFNULL(T1.OTHER_IDENTIFY_NAME,'')) = #{key,jdbcType=VARCHAR}
) where rank = 1

SELECT s1.* FROM CHB_EQU_HOLD s1 INNER join ( SELECT count(1),ch.REGIST_BANK_CODE,ch.PERSONAL_IDENTIFY_TYPE, ch.INSTITUTION_IDENTIFY_TYPE,ch.OTHER_IDENTIFY_NAME,ch.IDENTIFY_NUMBER,ch.HOLDER_NAME FROM CHB_EQU_HOLD ch INNER join CHB_equ_SUB cs ON ch.INDENTIFY_MARK=cs.INDENTIFY_MARK and ch.REGIST_BANK_CODE=cs.REGIST_BANK_CODE WHERE cs.SUBMIT_STATUS ='01' group by ch.REGIST_BANK_CODE, ch.PERSONAL_IDENTIFY_TYPE, ch.INSTITUTION_IDENTIFY_TYPE, ch.OTHER_IDENTIFY_NAME, ch.IDENTIFY_NUMBER, ch.HOLDER_NAME having count(1)>1 ) s2 on s1.REGIST_BANK_CODE=s2.REGIST_BANK_CODE and (s1.PERSONAL_IDENTIFY_TYPE=s2.PERSONAL_IDENTIFY_TYPE or(s1.PERSONAL_IDENTIFY_TYPE is null and s2.PERSONAL_IDENTIFY_TYPE is null )) and (s1.INSTITUTION_IDENTIFY_TYPE=s2.INSTITUTION_IDENTIFY_TYPE or(s1.INSTITUTION_IDENTIFY_TYPE is null and s2.INSTITUTION_IDENTIFY_TYPE is null )) and (s1.OTHER_IDENTIFY_NAME=s2.OTHER_IDENTIFY_NAME or(s1.OTHER_IDENTIFY_NAME is null and s2.OTHER_IDENTIFY_NAME is null )) and s1.IDENTIFY_NUMBER=s2.IDENTIFY_NUMBER and s1.HOLDER_NAME=s2.HOLDER_NAME where s1.status='E'
AND concat_ws('_',s1.REGIST_BANK_CODE,s1.IDENTIFY_NUMBER,IFNULL(s1.HOLDER_NAME,''),IFNULL(s1.PERSONAL_IDENTIFY_TYPE,''),IFNULL(s1.INSTITUTION_IDENTIFY_TYPE,''),IFNULL(s1.OTHER_IDENTIFY_NAME,'')) IN
#{key,jdbcType=VARCHAR}
